"""Data models for PDF rendering results."""

from pydantic import BaseModel, ConfigDict, Field


class RenderResult(BaseModel):
    """Result of PDF rendering containing generated bytes and processing metrics."""

    model_config = ConfigDict(frozen=True)

    pdf_bytes: bytes = Field(..., description="Raw bytes of the newly rendered PDF")
    page_count: int = Field(..., description="Total pages in the rendered PDF")
    rendered_blocks: int = Field(
        ...,
        description="Number of text blocks successfully substituted and rendered",
    )
    skipped_blocks: int = Field(
        ...,
        description="Number of blocks skipped without translation",
    )
    review_required_blocks: int = Field(
        ...,
        description="Number of blocks retained in original text due to layout review",
    )
    font_substitutions: int = Field(
        ...,
        description="Number of blocks where standard fallback fonts were used",
    )
    warnings: list[str] = Field(
        default_factory=list,
        description="Non-sensitive structured warnings logged during rendering",
    )
